const Username = type("string")
  .narrow((val): val is string => /^[a-zA-Z0-9]+$/.test(val) && !["admin", "root", "system"].includes(val));

const types = scope({
  User: {
    id: "string.uuid",
    username: Username,
    score: "string.numeric.parse",
    "friends?": "User[]"
  }
}).export();

console.log("Scope compiled successfully!");
const userType = types.User;
console.log("User type:", userType);

const result = userType.toJsonSchema({
  target: "draft-07",
  fallback: {
    morph: (ctx) => {
      console.log("morph fallback called!", ctx.code);
      return {
        type: "string",
        format: "morph-redacted",
        description: "morph dropped"
      };
    },
    predicate: (ctx) => {
      console.log("predicate fallback called!", ctx.code);
      return {
        ...ctx.base,
        "x-arktype-fallback": "predicate"
      };
    }
  }
});

