import { type, scope } from "arktype";

const Username = type("string")
  .narrow((val): val is string => /^[a-zA-Z0-9]+$/.test(val) && !["admin", "root", "system"].includes(val));

export const types = scope({
  User: {
    id: "string.uuid",
    username: Username,
    score: "string.numeric.parse",
    "friends?": "User[]"
  }
}).export();

export const User = types.User;

export const userJsonSchema = User.toJsonSchema({
  target: "draft-07",
  fallback: {
    morph: (ctx) => ({
      type: "string",
      format: "morph-redacted",
      description: "morph dropped"
    }),
    predicate: (ctx) => ({
      ...ctx.base,
      "x-arktype-fallback": "predicate"
    })
  }
});

import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { userJsonSchema } from "./src/user.ts";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const outDir = path.join(__dirname, "out");
const outFile = path.join(outDir, "user.schema.json");

if (!fs.existsSync(outDir)) {
  fs.mkdirSync(outDir, { recursive: true });
}

fs.writeFileSync(outFile, JSON.stringify(userJsonSchema, null, 2), "utf-8");

console.log(`WROTE ${path.resolve(outFile)}`);

process.exit(0);
